from pathlib import Path
import json

VERSION = "0.2.0-alpha.12"
PREVIOUS = "0.2.0-alpha.11"


def replace_once(text: str, old: str, new: str, label: str) -> str:
    if old not in text:
        raise SystemExit(f"missing expected block: {label}")
    return text.replace(old, new, 1)

Path('custom_components/dummy_os_data/do_plan_72h.py').write_text('''"""Observer-only Planner Step 5 sequential 72-hour simulation."""\n\nfrom __future__ import annotations\n\nfrom datetime import datetime, timezone\nimport math\nfrom typing import Any\n\nHOURS = 72\nCAPACITY_KWH = 7.2\nMIN_SOC_PERCENT = 5.0\nSAFETY_RESERVE_PERCENT = 7.0\nEXECUTION_BUFFER_PERCENT = 2.0\nCHARGE_EFFICIENCY_PERCENT = 92.0\nDISCHARGE_EFFICIENCY_PERCENT = 92.0\nMAX_CHARGE_POWER_W = 3200\nMAX_DISCHARGE_POWER_W = 3200\nEPS = 0.01\n\n\ndef _finite(value: Any, *, non_negative: bool = False) -> float | None:\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return None\n    if not math.isfinite(number):\n        return None\n    if non_negative and number < 0:\n        return None\n    return number\n\n\ndef _utc(value: Any) -> datetime | None:\n    if isinstance(value, datetime):\n        parsed = value\n    elif isinstance(value, str):\n        try:\n            parsed = datetime.fromisoformat(value)\n        except ValueError:\n            return None\n    else:\n        return None\n    if parsed.tzinfo is None:\n        return None\n    return parsed.astimezone(timezone.utc)\n\n\ndef _blocked(base: dict[str, Any], blockers: list[str]) -> dict[str, Any]:\n    return {**base, "status": "blocked", "valid": False, "reason": blockers[0], "blockers": sorted(set(blockers)), "hour_count": 0, "hours": [], "baseline": None, "candidate": None}\n\n\ndef _simulate(*, rows: list[dict[str, Any]], start_soc: float, reserve_soc: float, safety_hours: dict[str, float], trade: dict[str, Any] | None, charge_eff: float, discharge_eff: float) -> dict[str, Any]:\n    stored = CAPACITY_KWH * start_soc / 100.0\n    reserve_floor = CAPACITY_KWH * reserve_soc / 100.0\n    buffer_kwh = CAPACITY_KWH * EXECUTION_BUFFER_PERCENT / 100.0\n    execution_floor = min(CAPACITY_KWH, reserve_floor + buffer_kwh)\n    out: list[dict[str, Any]] = []\n    totals = {k: 0.0 for k in ("solar_to_home_kwh","solar_to_battery_kwh","solar_to_grid_kwh","grid_to_home_kwh","grid_to_battery_kwh","battery_to_home_kwh","battery_to_grid_kwh")}\n    reserve_breaches = 0\n    buffer_breaches = 0\n    for row in rows:\n        start_stored = stored\n        home = row["home_kwh"]\n        solar = row["solar_kwh"]\n        solar_to_home = min(home, solar)\n        remaining_home = home - solar_to_home\n        solar_surplus = solar - solar_to_home\n        charge_input_limit = MAX_CHARGE_POWER_W / 1000.0\n        solar_input = min(solar_surplus, charge_input_limit, max(0.0, (CAPACITY_KWH - stored) / charge_eff))\n        solar_to_battery = solar_input * charge_eff\n        stored += solar_to_battery\n        solar_to_grid = max(0.0, solar_surplus - solar_input)\n        charge_input_left = max(0.0, charge_input_limit - solar_input)\n\n        grid_to_battery_input = 0.0\n        safety_battery = safety_hours.get(row["start"], 0.0)\n        if safety_battery > EPS and charge_input_left > 0:\n            wanted_input = safety_battery / charge_eff\n            grid_to_battery_input = min(wanted_input, charge_input_left, max(0.0, (CAPACITY_KWH - stored) / charge_eff))\n            stored += grid_to_battery_input * charge_eff\n            charge_input_left -= grid_to_battery_input\n\n        action = "baseline"\n        if trade and trade.get("charge_time") == row["start"] and charge_input_left > 0:\n            trade_input = min(charge_input_left, max(0.0, (CAPACITY_KWH - stored) / charge_eff))\n            grid_to_battery_input += trade_input\n            stored += trade_input * charge_eff\n            action = "trade_charge"\n\n        max_batt_output = MAX_DISCHARGE_POWER_W / 1000.0\n        available_output = max(0.0, (stored - execution_floor) * discharge_eff)\n        battery_to_home = min(remaining_home, max_batt_output, available_output)\n        stored -= battery_to_home / discharge_eff\n        grid_to_home = remaining_home - battery_to_home\n        discharge_left = max(0.0, max_batt_output - battery_to_home)\n\n        battery_to_grid = 0.0\n        if trade and trade.get("discharge_time") == row["start"] and discharge_left > 0:\n            available_export = max(0.0, (stored - execution_floor) * discharge_eff)\n            battery_to_grid = min(discharge_left, available_export)\n            stored -= battery_to_grid / discharge_eff\n            action = "trade_discharge"\n\n        stored = min(CAPACITY_KWH, max(0.0, stored))\n        end_soc = stored / CAPACITY_KWH * 100.0\n        if stored + EPS < reserve_floor:\n            reserve_breaches += 1\n        if stored + EPS < execution_floor:\n            buffer_breaches += 1\n\n        values = {\n            "solar_to_home_kwh": solar_to_home, "solar_to_battery_kwh": solar_to_battery, "solar_to_grid_kwh": solar_to_grid,\n            "grid_to_home_kwh": grid_to_home, "grid_to_battery_kwh": grid_to_battery_input, "battery_to_home_kwh": battery_to_home, "battery_to_grid_kwh": battery_to_grid,\n        }\n        for key, value in values.items(): totals[key] += value\n        out.append({\n            "index": row["index"], "start": row["start"], "end": row["end"], "start_soc_percent": round(start_stored / CAPACITY_KWH * 100.0, 3), "end_soc_percent": round(end_soc, 3),\n            "reserve_floor_soc_percent": round(reserve_soc, 3), "execution_floor_soc_percent": round(execution_floor / CAPACITY_KWH * 100.0, 3), "action": action,\n            **{k: round(v, 3) for k,v in values.items()},\n        })\n    return {"hours": out, "end_soc_percent": round(stored / CAPACITY_KWH * 100.0, 3), "reserve_breach_hours": reserve_breaches, "execution_buffer_breach_hours": buffer_breaches, **{k: round(v, 3) for k,v in totals.items()}}\n\n\ndef build_do_plan_72h(*, input_result: dict[str, Any], reserve_result: dict[str, Any], preview_result: dict[str, Any]) -> dict[str, Any]:\n    """Build exact 72-hour observer-only sequential planner simulation."""\n    base = {\n        "shadow_only": True, "active_use_permitted": False, "physical_execution_authority": False,\n        "plan_store_write": False, "scheduler_invoked": False, "safety_chain_invoked": False, "service_calls_performed": False,\n        "native_resolution_minutes": 15, "native_slot_count": 288, "planner_resolution_minutes": 60, "planner_hour_count": 72,\n        "input_rows_signature": input_result.get("rows_signature"), "reserve_input_rows_signature": reserve_result.get("input_rows_signature"), "preview_input_rows_signature": preview_result.get("input_rows_signature"),\n        "calculation_scope": "sequential_72h_observer_simulation",\n    }\n    blockers: list[str] = []\n    if input_result.get("status") != "ready" or input_result.get("fully_valid_hours") != HOURS: blockers.append("planner_input_not_ready")\n    if reserve_result.get("status") != "ready" or reserve_result.get("valid") is not True: blockers.append("reserve_soc_not_ready")\n    if preview_result.get("status") != "ready" or preview_result.get("valid") is not True: blockers.append("planner_preview_not_ready")\n    sig = input_result.get("rows_signature")\n    if sig is None or reserve_result.get("input_rows_signature") != sig or preview_result.get("input_rows_signature") != sig: blockers.append("input_signature_mismatch")\n    raw_rows = input_result.get("rows")\n    if not isinstance(raw_rows, list) or len(raw_rows) != HOURS: blockers.append("rows_not_exactly_72")\n    soc = _finite(reserve_result.get("soc_percent"), non_negative=True)\n    reserve_soc = _finite(reserve_result.get("reserve_soc_target_percent"), non_negative=True)\n    if soc is None or soc > 100: blockers.append("soc_invalid")\n    if reserve_soc is None or reserve_soc > 100: blockers.append("reserve_soc_invalid")\n\n    rows: list[dict[str, Any]] = []\n    if isinstance(raw_rows, list):\n        previous_end = None\n        for i, raw in enumerate(raw_rows):\n            if not isinstance(raw, dict) or raw.get("fully_valid") is not True: blockers.append(f"row_{i}_not_fully_valid"); continue\n            start=_utc(raw.get("start")); end=_utc(raw.get("end")); home=_finite(raw.get("home_kwh"), non_negative=True); solar=_finite(raw.get("solar_kwh"), non_negative=True); imp=_finite(raw.get("import_price")); exp=_finite(raw.get("export_price"))\n            if None in (start,end,home,solar,imp,exp): blockers.append(f"row_{i}_invalid"); continue\n            if raw.get("index") != i: blockers.append(f"row_{i}_index_mismatch")\n            if previous_end is not None and start != previous_end: blockers.append(f"row_{i}_not_contiguous")\n            previous_end=end\n            rows.append({"index":i,"start":start.isoformat(),"end":end.isoformat(),"home_kwh":home,"solar_kwh":solar,"import_price":imp,"export_price":exp})\n    if blockers: return _blocked(base, blockers)\n    assert soc is not None and reserve_soc is not None\n    charge_eff=CHARGE_EFFICIENCY_PERCENT/100.0; discharge_eff=DISCHARGE_EFFICIENCY_PERCENT/100.0\n    safety_hours: dict[str,float] = {}\n    for item in preview_result.get("safety_charge_hours") or []:\n        if isinstance(item, dict):\n            start=item.get("start"); energy=_finite(item.get("candidate_battery_energy_kwh"), non_negative=True)\n            if isinstance(start,str) and energy is not None: safety_hours[start]=energy\n    trade = None\n    candidates=[]\n    if preview_result.get("self_use_trade_profitable"):\n        candidates.append((preview_result.get("best_self_use_margin"), preview_result.get("best_self_use_charge_time"), preview_result.get("best_self_use_discharge_time"), "self_use"))\n    if preview_result.get("export_trade_profitable"):\n        candidates.append((preview_result.get("best_export_margin"), preview_result.get("best_export_charge_time"), preview_result.get("best_export_discharge_time"), "export"))\n    valid_candidates=[]\n    for margin, charge_time, discharge_time, kind in candidates:\n        m=_finite(margin)\n        if m is not None and isinstance(charge_time,str) and isinstance(discharge_time,str): valid_candidates.append((m,charge_time,discharge_time,kind))\n    if valid_candidates:\n        m,ct,dt,kind=max(valid_candidates,key=lambda x:x[0]); trade={"margin":m,"charge_time":ct,"discharge_time":dt,"kind":kind}\n    baseline=_simulate(rows=rows,start_soc=soc,reserve_soc=reserve_soc,safety_hours=safety_hours,trade=None,charge_eff=charge_eff,discharge_eff=discharge_eff)\n    candidate=_simulate(rows=rows,start_soc=soc,reserve_soc=reserve_soc,safety_hours=safety_hours,trade=trade,charge_eff=charge_eff,discharge_eff=discharge_eff)\n    solar_displacement=max(0.0, baseline["solar_to_battery_kwh"]-candidate["solar_to_battery_kwh"])\n    infeasible = candidate["reserve_breach_hours"] > 0 or candidate["execution_buffer_breach_hours"] > 0\n    return {**base, "status": "infeasible" if infeasible else "ready", "valid": not infeasible, "reason": "reserve_or_execution_buffer_breach" if infeasible else "sequential_simulation_complete", "blockers": ["simulated_reserve_breach"] if infeasible else [], "hour_count": HOURS, "hours": candidate["hours"], "baseline": {k:v for k,v in baseline.items() if k!="hours"}, "candidate": {k:v for k,v in candidate.items() if k!="hours"}, "trade_candidate": trade, "solar_displacement_kwh": round(solar_displacement,3), "losses_included": True, "reserve_recalculated": False, "missing_as_zero_used": False}\n''')

Path('custom_components/dummy_os_data/do_plan_72h_sensor.py').write_text('''"""Home Assistant sensor adapter for observer-only Planner Step 5."""\n\nfrom __future__ import annotations\nfrom typing import Any\nfrom .do_plan_72h import build_do_plan_72h\nfrom .do_plan_preview import build_do_plan_preview\n\n\ndef build_do_plan_72h_sensors(coordinator: Any) -> list[Any]:\n    from .sensor import DummyOSPlanReserveSOCSensor, _build_plan_input_from_snapshot, _build_reserve_from_snapshot\n\n    class DummyOSPlan72hSensor(DummyOSPlanReserveSOCSensor):\n        _attr_name = "DO Plan 72h"\n        _attr_unique_id = "do_plan_72h"\n        _attr_suggested_object_id = "do_plan_72h"\n        _attr_icon = "mdi:timeline-clock-outline"\n        _unrecorded_attributes = frozenset({"hours"})\n\n        def _calculate_result(self, snapshot: dict[str, Any]) -> dict[str, Any]:\n            input_result = _build_plan_input_from_snapshot(snapshot)\n            reserve_result = _build_reserve_from_snapshot(snapshot)\n            preview_result = build_do_plan_preview(input_result=input_result, reserve_result=reserve_result, now=snapshot["now"], charge_efficiency_percent=92.0, discharge_efficiency_percent=92.0, minimum_trade_margin=0.10, max_charge_power_w=3200, max_discharge_power_w=3200)\n            result = build_do_plan_72h(input_result=input_result, reserve_result=reserve_result, preview_result=preview_result)\n            result["input_entity"] = "sensor.do_plan_input_72h"\n            result["reserve_entity"] = "sensor.do_plan_reserve_soc"\n            result["preview_entity"] = "sensor.do_plan_preview"\n            result["soc_source_entity"] = reserve_result.get("soc_source_entity")\n            result["source_layer_status"] = reserve_result.get("source_layer_status")\n            return result\n\n        def _initial_result(self) -> dict[str, Any]:\n            return {"status":"initializing","valid":False,"hour_count":0,"hours":[],"shadow_only":True,"active_use_permitted":False,"physical_execution_authority":False,"plan_store_write":False,"scheduler_invoked":False,"safety_chain_invoked":False,"service_calls_performed":False,"blockers":["planner_calculation_pending"]}\n\n        @property\n        def native_value(self) -> str:\n            return str(self._result().get("status", "initializing"))\n\n        @property\n        def extra_state_attributes(self) -> dict[str, Any]:\n            return dict(self._result())\n\n    return [DummyOSPlan72hSensor(coordinator)]\n''')

sensor_path=Path('custom_components/dummy_os_data/sensor.py'); sensor=sensor_path.read_text()
sensor=replace_once(sensor, 'from .do_plan_preview_sensor import build_do_plan_preview_sensors\n', 'from .do_plan_preview_sensor import build_do_plan_preview_sensors\nfrom .do_plan_72h_sensor import build_do_plan_72h_sensors\n', 'sensor import')
sensor=replace_once(sensor, '            *build_do_plan_preview_sensors(coordinator),\n', '            *build_do_plan_preview_sensors(coordinator),\n            *build_do_plan_72h_sensors(coordinator),\n', 'sensor setup')
sensor_path.write_text(sensor)

for path in ['custom_components/dummy_os_data/const.py','tests/test_release_consistency.py']:
    p=Path(path); t=p.read_text(); t=replace_once(t,f'VERSION = "{PREVIOUS}"',f'VERSION = "{VERSION}"',path); p.write_text(t)
p=Path('custom_components/dummy_os_data/manifest.json'); d=json.loads(p.read_text());
if d.get('version') != PREVIOUS: raise SystemExit('unexpected manifest version')
d['version']=VERSION; p.write_text(json.dumps(d,indent=2)+'\n')

Path('tests/test_do_plan_72h.py').write_text('''from datetime import datetime, timedelta, timezone\nfrom custom_components.dummy_os_data.do_plan_72h import build_do_plan_72h\n\ndef make_rows():\n    start=datetime(2026,9,10,tzinfo=timezone.utc)\n    return [{"index":i,"start":(start+timedelta(hours=i)).isoformat(),"end":(start+timedelta(hours=i+1)).isoformat(),"home_kwh":0.5,"solar_kwh":0.0,"import_price":0.2,"export_price":0.1,"fully_valid":True} for i in range(72)]\n\ndef base_inputs():\n    rows=make_rows(); sig='abc'\n    inp={"status":"ready","fully_valid_hours":72,"rows_signature":sig,"rows":rows}\n    reserve={"status":"ready","valid":True,"input_rows_signature":sig,"soc_percent":80.0,"reserve_soc_target_percent":12.0}\n    preview={"status":"ready","valid":True,"input_rows_signature":sig,"safety_charge_hours":[],"self_use_trade_profitable":False,"export_trade_profitable":False}\n    return inp,reserve,preview\n\ndef test_exact_72_and_observer_rights():\n    i,r,p=base_inputs(); out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p)\n    assert out['hour_count']==72 and len(out['hours'])==72\n    assert out['shadow_only'] is True and out['active_use_permitted'] is False and out['physical_execution_authority'] is False\n    assert out['plan_store_write'] is False and out['scheduler_invoked'] is False and out['safety_chain_invoked'] is False and out['service_calls_performed'] is False\n\ndef test_signature_mismatch_blocks():\n    i,r,p=base_inputs(); p['input_rows_signature']='wrong'; out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert out['status']=='blocked' and 'input_signature_mismatch' in out['blockers']\n\ndef test_missing_value_blocks_not_zero():\n    i,r,p=base_inputs(); i['rows'][3]['home_kwh']=None; out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert out['status']=='blocked' and out['hour_count']==0\n\ndef test_real_zero_is_valid():\n    i,r,p=base_inputs(); i['rows'][0]['home_kwh']=0.0; i['rows'][0]['solar_kwh']=0.0; out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert out['status'] in {'ready','infeasible'} and out['missing_as_zero_used'] is False\n\ndef test_solar_first_and_shared_charge_limit():\n    i,r,p=base_inputs(); i['rows'][0]['home_kwh']=0.5; i['rows'][0]['solar_kwh']=4.0; p['safety_charge_hours']=[{"start":i['rows'][0]['start'],"candidate_battery_energy_kwh":2.0}]; out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); h=out['hours'][0]; assert h['solar_to_home_kwh']==0.5; assert h['grid_to_battery_kwh'] <= 3.2\n\ndef test_trade_two_pass_reports_displacement():\n    i,r,p=base_inputs(); i['rows'][1]['solar_kwh']=5.0; p.update({"self_use_trade_profitable":True,"best_self_use_margin":0.2,"best_self_use_charge_time":i['rows'][0]['start'],"best_self_use_discharge_time":i['rows'][2]['start']}); out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert out['baseline'] is not None and out['candidate'] is not None and out['solar_displacement_kwh'] >= 0\n\ndef test_full_battery_never_overfills():\n    i,r,p=base_inputs(); r['soc_percent']=100.0; i['rows'][0]['solar_kwh']=4.0; out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert max(h['end_soc_percent'] for h in out['hours']) <= 100.0\n\ndef test_export_trade_uses_explicit_candidate():\n    i,r,p=base_inputs(); p.update({"export_trade_profitable":True,"best_export_margin":0.3,"best_export_charge_time":i['rows'][0]['start'],"best_export_discharge_time":i['rows'][1]['start']}); out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert out['trade_candidate']['kind']=='export'\n\ndef test_upstream_not_ready_blocks():\n    i,r,p=base_inputs(); i['status']='runtime_blocked'; out=build_do_plan_72h(input_result=i,reserve_result=r,preview_result=p); assert out['status']=='blocked'\n''')

Path('tests/test_do_plan_72h_sensor_contract.py').write_text('''from pathlib import Path\nROOT=Path(__file__).parents[1]\n\ndef test_sensor_registered_and_executor_backed():\n    sensor=(ROOT/'custom_components/dummy_os_data/sensor.py').read_text(); adapter=(ROOT/'custom_components/dummy_os_data/do_plan_72h_sensor.py').read_text()\n    assert 'build_do_plan_72h_sensors' in sensor and '*build_do_plan_72h_sensors(coordinator)' in sensor\n    assert '_attr_unique_id = "do_plan_72h"' in adapter\n    assert 'DummyOSPlanReserveSOCSensor' in adapter\n\ndef test_no_execution_authority_in_step5_module():\n    text=(ROOT/'custom_components/dummy_os_data/do_plan_72h.py').read_text()\n    for needle in ('"shadow_only": True','"active_use_permitted": False','"physical_execution_authority": False','"plan_store_write": False','"scheduler_invoked": False','"safety_chain_invoked": False','"service_calls_performed": False'):\n        assert needle in text\n''')

notes='''# GitHub Release\n\n**Tag:** `0.2.0-alpha.12`  \n**Release title:** Dummy OS Energy 0.2.0-alpha.12 - Planner Step 5 72h Sequential Simulation\n\n## Dummy OS Energy 0.2.0-alpha.12\n\nDeze prerelease implementeert Planner Stap 5 als observer-only `DO Plan 72h` sequentiële simulatie bovenop de bestaande gevalideerde Planner Stap 1-4 keten.\n\n### Toegevoegd\n- Exact 72 volledige planneruren als sequentiële batterijsimulatie.\n- Twee simulatiepasses: baseline zonder trade en candidate met uitsluitend de Stap-4 tradecandidate.\n- Solar-first energiestroom en gedeelde 3200 W laadlimiet voor solar + grid.\n- 7,2 kWh batterij, 5% minimum-SOC, 7% software-reserve, 2% diagnostische execution-buffer en 92%/92% efficiency.\n- Uurdiagnostiek voor SOC en energieflows; baseline/candidate samenvatting en `solar_displacement_kwh`.\n- Strikte upstream signature/72h-validatie; missing/NaN wordt niet als nul behandeld.\n\n### Safetyrechten onveranderd\n- `shadow_only=true`\n- `active_use_permitted=false`\n- `physical_execution_authority=false`\n- `plan_store_write=false`\n- `scheduler_invoked=false`\n- `safety_chain_invoked=false`\n- `service_calls_performed=false`\n\nEr wordt geen plan opgeslagen, geen scheduler aangeroepen en geen fysieke batterijactie uitgevoerd.\n\n### Live-validatie\nControleer na installatie `sensor.do_plan_72h`: status, `hour_count=72`, signatures, safetyflags, baseline/candidate, SOC-verloop en afwezigheid van nieuwe `dummy_os_data` main-threadwaarschuwingen.\n'''
Path(f'RELEASE_NOTES_{VERSION}.md').write_text(notes)
h=Path('RELEASE_NOTES.md'); cur=h.read_text();
if f'**Tag:** `{VERSION}`' in cur: raise SystemExit('release notes already present')
h.write_text(notes+'\n---\n'+cur)
